INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10071003, "物理防御力（ダウン不可）アップ", "boss_def_lower_limit", "バトル開始時、すべてのモンスターの物理防御力をアップさせる。この効果は物理防御力ダウンの影響を受けない。", 4100710);
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10071004, "魔法防御力（ダウン不可）アップ", "boss_magic_def_lower_limit", "バトル開始時、すべてのモンスターの魔法防御力をアップさせる。この効果は魔法防御力ダウンの影響を受けない。", 4100710);
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10071005, "ＴＰダウンカット", "boss_tp_down_cut", "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。", 4100710);
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10071006, "ＴＰ上昇ダウン", 3, "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。", 4100710);
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10071007, "ＨＰ吸収ダウン", 9, "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。", 4100710);
